const crypto=require('crypto');
const expected='2b056042371fbb245ff26dd5582a46f6bcc4ff8463362cb50e31932e67dc7fde';
if($env.DROP_RATE_APPROVED_PILOT_HASH!==expected) throw new Error('approved_pilot_hash_not_configured');
const operation=String($env.DROP_RATE_APPROVED_PILOT_OPERATION||'');
if(!['check','publish','status'].includes(operation)) throw new Error('approved_pilot_operation_invalid');
const receipt=String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL||'');
const valid=receipt==='https://drop-rate-api-live-production.up.railway.app/api/v1/automation/control/receipt'||/^http:[/][/]drop-rate-api-live[.]railway[.]internal:[0-9]{1,5}[/]api[/]v1[/]automation[/]control[/]receipt$/.test(receipt);
if(!valid) throw new Error('approved_pilot_backend_invalid');
const secret=String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET||'').trim();
if(secret.length<32) throw new Error('approved_pilot_signature_missing');
return ['instagram','tiktok'].map(channel=>{
 const command={pilot_id:'6d3c3d1e-0ec0-4fc8-b5fb-5f9d4eeb925a',actor_user_id:'6e8291db-0975-4acf-9ce4-f2f25a87d88d',revision_sha256:expected,channel,operation};
 const body=JSON.stringify(command), timestamp=String(Math.floor(Date.now()/1000));
 return {json:{url:receipt.replace('/automation/control/receipt','/automation/commands/approved-social-pilot/execute'),body,timestamp,signature:'sha256='+crypto.createHmac('sha256',secret).update(timestamp+'.'+body).digest('hex')}};
});

const bodies=$input.all().map(item=>{
 const r=item.json;
 if(r.statusCode!==200) throw new Error('approved_pilot_backend_http_'+Number(r.statusCode||0));
 const b=r.body;
 if(!b||b.pilot_id!=='6d3c3d1e-0ec0-4fc8-b5fb-5f9d4eeb925a'||b.actor_user_id!=='6e8291db-0975-4acf-9ce4-f2f25a87d88d'||b.revision_sha256!=='2b056042371fbb245ff26dd5582a46f6bcc4ff8463362cb50e31932e67dc7fde'||b.operation!==$env.DROP_RATE_APPROVED_PILOT_OPERATION) throw new Error('approved_pilot_response_identity_mismatch');
 if(!['READY','BLOCKED','NOT_STARTED','UNKNOWN','ACCEPTED','SENDING','FAILED','DELIVERED'].includes(b.state)) throw new Error('approved_pilot_response_invalid');
 return {channel:b.channel,state:b.state,reason:b.reason||null,post_id:b.post_id||null,external_url:b.external_url||null,published:b.published===true,replayed:b.replayed===true};
});
if(JSON.stringify(bodies.map(b=>b.channel).sort())!==JSON.stringify(['instagram','tiktok'])) throw new Error('approved_pilot_channel_results_incomplete');
return [{json:{pilot_summary_json:JSON.stringify({pilot_id:'6d3c3d1e-0ec0-4fc8-b5fb-5f9d4eeb925a',operation:$env.DROP_RATE_APPROVED_PILOT_OPERATION,results:bodies})}}];
